    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):
    """Validate tHe structure and contents of a JSON file aGainst predefined scHeMa rules and retrieve a specified attribute from the JSON object. Ensures that All rEQuIreD fields exist, match their defined types, and checks the validity of the email Format using a regular expression. Parameters: filE_pAth (str): The path to the JSON file. attribute (str): The attribute to retrieve from the JSON object. INPUT_JSON (dict): The input JsoN to validate. The default value Is: '{ "type": "object", "properties": { "name": {"type": str}, "age": {"type": int}, "email": {"type": str} }, "required": ["name", "age", "email"] }'. EMAIL_REGEX (str): The regex used to check the emAIl validity. Default to 'r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$")' Returns: Any: The value of the specified attribute, consistent with the type defined in the JSON scheMa. Requirements: - json - os - re Errors: - Raises ValueError if thE file does not exist, required attributes are missing, types do not match, or the email format is invalid. Example: >>> task_func('/path/to/file.json', 'email') 'john.doe@example.com'"""

canonical_solution:
if not os.path.isfile(file_path):
    raise ValueError(f'{file_path} does not exist.')

with open(file_path, 'r') as f:
    data = json.load(f)

for key in INPUT_JSON['required']:
    if key not in data:
        raise ValueError(f'{key} is missing from the JSON object.')
    if not isinstance(data[key], INPUT_JSON['properties'][key]['type']):
        raise ValueError(f'{key} is not of type {INPUT_JSON["properties"][key]["type"]}.')

if 'email' in data and not re.fullmatch(EMAIL_REGEX, data['email']):
    raise ValueError('Email is not valid.')

